// Loads the golf library and answers questions about it.
//
//   content/library.json   — the category → topic → subtopic tree (hand-edited)
//   content/manifest.json  — one entry per lesson, generated by tools/build-content.mjs
//   content/articles/**.md — the lessons themselves (Markdown, editable in Obsidian)

import { renderArticle } from './render.js';

async function fetchJSON(url) {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`Could not load ${url} (${res.status})`);
  return res.json();
}

export async function loadContent() {
  const [library, manifest] = await Promise.all([
    fetchJSON('content/library.json'),
    fetchJSON('content/manifest.json'),
  ]);

  const categories = library.categories;
  const categoryById = new Map();
  const topicById = new Map(); // topic or subtopic id → { node, category, parent }

  for (const cat of categories) {
    categoryById.set(cat.id, cat);
    for (const topic of cat.topics || []) {
      topicById.set(topic.id, { node: topic, category: cat, parent: null });
      for (const sub of topic.subtopics || []) {
        topicById.set(sub.id, { node: sub, category: cat, parent: topic });
      }
    }
  }

  const articles = new Map(manifest.articles.map((a) => [a.id, a]));
  const byOrder = (a, b) => (a.order ?? 999) - (b.order ?? 999) || a.title.localeCompare(b.title);

  // Lessons filed directly under a topic or subtopic id.
  const filedUnder = new Map();
  for (const a of articles.values()) {
    if (!filedUnder.has(a.topic)) filedUnder.set(a.topic, []);
    filedUnder.get(a.topic).push(a);
  }
  for (const list of filedUnder.values()) list.sort(byOrder);

  const htmlCache = new Map();

  const api = {
    categories,
    articles,
    featured: (library.featured || []).map((id) => articles.get(id)).filter(Boolean),

    category: (id) => categoryById.get(id),
    topic: (id) => topicById.get(id),

    /** Lessons filed directly under this topic/subtopic. */
    lessonsIn: (topicId) => filedUnder.get(topicId) || [],

    /** Lessons under a topic including its subtopics. */
    lessonsUnder(topicId) {
      const t = topicById.get(topicId);
      if (!t) return [];
      const own = api.lessonsIn(topicId);
      const subs = (t.node.subtopics || []).flatMap((s) => api.lessonsIn(s.id));
      return [...own, ...subs];
    },

    countInCategory(catId) {
      const cat = categoryById.get(catId);
      return (cat?.topics || []).reduce((n, t) => n + api.lessonsUnder(t.id).length, 0);
    },

    /** Where a lesson lives: { category, topic, subtopic } */
    placeOf(article) {
      const t = topicById.get(article.topic);
      if (!t) return { category: null, topic: null, subtopic: null };
      return t.parent
        ? { category: t.category, topic: t.parent, subtopic: t.node }
        : { category: t.category, topic: t.node, subtopic: null };
    },

    topicPath: (catId, topicId) => `/library/${catId}/${topicId}`,
    lessonPath: (id) => `/lesson/${id}`,

    async articleHtml(id) {
      if (htmlCache.has(id)) return htmlCache.get(id);
      const a = articles.get(id);
      if (!a) throw new Error(`Unknown lesson: ${id}`);
      const res = await fetch(a.path);
      if (!res.ok) throw new Error(`Could not load lesson (${res.status})`);
      const html = await renderArticle(await res.text(), a.path, api);
      htmlCache.set(id, html);
      return html;
    },
  };

  return api;
}
